{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative (sentiment < 0) or shows recent negative momentum.",
    "Reduce forecast overshoots following sharp price spikes by applying a 10-15% dampening factor to the immediate next period.",
    "Apply mean reversion bias: if forecast is > 5% above recent 7-day average, reduce by 1-2% per day until convergence.",
    "Increase forecast sensitivity to recent low prices when sentiment is neutral or positive (sentiment = 0) and prices are trending downward.",
    "For long-term horizons (>10 days), apply a 5-10% downward bias if true outcomes consistently underperform forecasts.",
    "When sentiment is positive and forecast is below true outcome, increase forecast by 2-3% to capture sentiment-driven momentum."
  ]
}
